Section SIDE.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

  Definition ipf_side (LF : list fframe) (m0 m : mem) (lo shi ff fp P E p0 n : Z) : Prop :=
    as_RFS H ((7, ff, fp) :: LF) m /\ pside2 m lo shi [(P, 256); (E, 24); (p0, n)] [(E, 24); (p0, n)]
    /\ aapp P 256 /\ aapp E 24 /\ aapp p0 n /\ 0 <= n /\ fsobj H LF P 256 /\ fsobj H LF E 24 /\ fsobj H LF p0 n
    /\ (exists mW, as_RFS H LF mW).   (* [comment removed for export] *)

  (* [comment removed for export] *)
  Definition iwin (ff P E : Z) (iv : Z * Z) : Prop :=
    aceil <= fst iv \/ (ff <= fst iv /\ snd iv <= ff + 8192) \/ (P <= fst iv /\ snd iv <= P + 256) \/ (E <= fst iv /\ snd iv <= E + 24)
    \/ iv = (AG_HTTP_CAT, AG_HTTP_CAT + 64) \/ (AG_FIELD_TABLE <= fst iv /\ snd iv <= AG_FIELD_TABLE + 3456).

  Lemma ipf_ff_nums : forall LF m0 m lo shi ff fp P E p0 n,
    ipf_side LF m0 m lo shi ff fp P E p0 n ->
    fresh_frame H LF 7 ff fp /\ aapp ff 8192
    /\ 6848512 <= ff /\ ff + 8192 <= aceil /\ ff mod 8 = 0 /\ 6815744 <= fp /\ fp + 1 <= ff
    /\ 2148302336 <= Z.shiftr ff 3 + 2147450880 /\ Z.shiftr ff 3 + 2147450880 + 1024 <= 17594333495296
    /\ Z.shiftr ff 3 + 2147450880 = sh ff
    /\ (ff + 8192 <= 2147446784 \/ 17594333495296 <= ff)
    /\ (fp + 1 <= 2147446784 \/ 17594333495296 <= fp)
    /\ ff mod 64 = 0.
  Proof.
    intros LF m0 m lo shi ff fp P E p0 n (RF & _).
    pose proof (fresh_of_RFS _ HH _ _ _ _ _ RF) as FF.
    pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & F3' & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & SF1 & SF2 & SF3 & NSB).
    fs_nums_in F2. fs_nums_in APF. fs_nums_in SF2.
    pose proof (aapp_not_shadowland _ _ APF) as NSF. pose proof (aapp_not_shadowland _ _ APP1) as NSP.
    unfold AIMG_TOP, AFS_HDR, AFS_FLAGS, AHI_LO, ALOWSH_LO in *. rewrite <- SHFF in SF1, SF2.
    repeat (split; [first [assumption | lia]|]). exact F3'.
  Qed.
