  Lemma iwin_pwin : forall LF m0 m lo shi ff fp P E p0 n iv,
    ipf_side LF m0 m lo shi ff fp P E p0 n -> iwin ff P E iv -> pwin iv.
  Proof.
    intros LF m0 m lo shi ff fp P E p0 n [l h] SD D.
    destruct (ipf_ff_nums _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & _). destruct SD as (_ & _ & APP & APE & _).
    destruct D as [K|[[K1 K2]|[[K1 K2]|[[K1 K2]|[K|[K1 K2]]]]]]; cbn [fst snd] in *.
