  (* [comment removed for export] *)
  Lemma ipf_side_step_sh : forall LF m0 m m' lo shi ff fp P E p0 n l h cs1 cs2,
    ipf_side LF m0 m lo shi ff fp P E p0 n ->
    munch [(l, h)]%Z m m' -> wmono asegs m m' ->
    Z.shiftr ff 3 + 2147450880 <= l -> h <= Z.shiftr ff 3 + 2147450880 + 552 ->
    rw_cells asegs m' (Z.shiftr ff 3 + 2147450880) cs1 -> Z.of_nat (cells_size cs1) = 552 ->
