  Lemma ipf_side_RFS : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> as_RFS H ((7, ff, fp) :: LF) m.
  Proof. intros until n. intros (K & _). exact K. Qed.
  Lemma ipf_side_ps : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> pside2 m lo shi [(P, 256); (E, 24); (p0, n)] [(E, 24); (p0, n)].
  Proof. intros until n. intros (_ & K & _). exact K. Qed.
  Lemma ipf_side_aconst : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> ACONST m.
  Proof. intros until n. intros (_ & K & _). exact (pside2_aconst _ _ _ _ _ K). Qed.
  Lemma ipf_side_stack0 : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> stack0 m lo shi.
  Proof. intros until n. intros (_ & K & _). exact (pside2_stack0 _ _ _ _ _ K). Qed.
  Lemma ipf_side_statics2 : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> AXStatics2 m.
