  Lemma ipf_side_accP : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> accessible m P 256.
  Proof. intros until n. intros (_ & K & _). exact (pside2_acc _ _ _ _ _ P 256 K ltac:(ps_in)). Qed.
  Lemma ipf_side_accE : forall LF m0 m lo shi ff fp P E p0 n, ipf_side LF m0 m lo shi ff fp P E p0 n -> accessible m E 24.
