Section MONO.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Lemma ipf_fresh_frame_tail : forall f LF k ff fp, fresh_frame H (f :: LF) k ff fp -> fresh_frame H LF k ff fp.
  Proof.
    intros f LF k ff fp (AR & FB & D). split; [exact AR|]. split; [exact FB|]. intros g Hg. apply D. right. exact Hg.
  Qed.
  Lemma ipf_fs_scratch_tail : forall f LF iv, fs_scratch H (f :: LF) iv -> fs_scratch H LF iv.
  Proof.
    intros f LF iv [E|(k & ff & fp & FF & E)]; [left; exact E| right].
    exists k, ff, fp. split; [eapply ipf_fresh_frame_tail; exact FF| exact E].
  Qed.
  Lemma ipf_Forall_scratch_tail : forall f LF XS, Forall (fs_scratch H (f :: LF)) XS -> Forall (fs_scratch H LF) XS.
  Proof. intros f LF XS FX. eapply Forall_impl; [| exact FX]. intros iv K. eapply ipf_fs_scratch_tail. exact K. Qed.
  Lemma ipf_fsobj_cons : forall LF f O n, fsobj H LF O n -> fsobj H (f :: LF) O n.
  Proof. intros LF f O n [K|(g & IN & K1 & K2)]; [left; exact K| right; exists g; split; [right; exact IN| split; assumption]]. Qed.
  Lemma ipf_aobj_consF : forall LB LF f A n, aobj LB LF A n -> aobj LB (f :: LF) A n.
  Proof. intros LB LF f A n [K|(g & IN & K1 & K2)]; [left; exact K| right; exists g; split; [right; exact IN| split; assumption]]. Qed.
End MONO.

