Section CATW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Lemma ipf_cat_window_ok : forall s LB m LF m1, as_RHEAP H s LB m -> as_RFS H LF m1 ->
    aclient_write_ok H LB (6667152, 6667152 + 64) /\ afs_write_ok H LF (6667152, 6667152 + 64) /\ aconst_ok (6667152, 6667152 + 64).
  Proof.
    intros s LB m LF m1 RH RF. pose proof (RFS_fsb _ HH _ _ RF) as (B1 & B2 & B3 & B4).
    split; [| split].
    - right; left. unfold aimg_client_w, ATLS_PRIV_LO, ATP. cbn [fst snd]. right; right; right; left. clear. lia.
    - left. cbn [fst snd]. unfold AIMG_TOP, ATLS_PRIV_LO, ATP in *. clear - B1. lia.
    - pose proof pwin_httpcat as [(K & _) _]. unfold AG_HTTP_CAT in K. exact K.
  Qed.
  (* [comment removed for export] *)
  Lemma ipf_tab_window_ok : forall s LB m LF m1, as_RHEAP H s LB m -> as_RFS H LF m1 ->
    aclient_write_ok H LB (6667216, 6667216 + 3456) /\ afs_write_ok H LF (6667216, 6667216 + 3456).
  Proof.
    intros s LB m LF m1 RH RF. pose proof (RFS_fsb _ HH _ _ RF) as (B1 & B2 & B3 & B4).
    split.
    - right; left. unfold aimg_client_w, ATLS_PRIV_LO, ATP. cbn [fst snd]. right; right; right; left. clear. lia.
    - left. cbn [fst snd]. unfold AIMG_TOP, ATLS_PRIV_LO, ATP in *. clear - B1. lia.
  Qed.
